\label{thm.7.2.003}
{\rm (Milnor \cite{Milnor})} 
In the situation as above, assume that 
the complex hypersurface $X_0=f^{-1}(0)\subset X$ 
has an isolated singular point at a point 
$x \in X_0=f^{-1}(0)\subset X$. 
Then the Milnor fiber $F_x \subset X \setminus X_0$ of $f$ at it 
is homotopy equivalent to the bouquet of some 
$(n-1)$-dimensional spheres $S^{n-1}$: 
\begin{equation}
F_x  \sim  S^{n-1}\vee\cdots\vee S^{n-1}.
\end{equation}
In particular, for its cohomology groups 
$H^j(F_x; {\mathbb C} )$ ($j \in {\mathbb Z}$) we have 
\begin{equation}
H^j(F_x; {\mathbb C} ) \simeq 
\begin{cases}
\ {\mathbb C} & (j=0) \\
& \\
\ {\mathbb C}^{\mu} & (j=n-1) \\
 & \\
\ 0 & (j \neq 0,n-1), 
\end{cases}
\end{equation}
where $\mu>0$ is the number of spheres $S^{n-1}$ in 
the above bouquet decomposition.

\label{def.7.1.001}
{\rm (Deligne~\cite{Deligne})} 
For ${\cal F} \in {\bf D}^{\mathrm{b}} (X)$ we define its nearby cycle 
complex $\psi_f( {\cal F} )\in {\bf D}^{\mathrm{b}} (X_0)$ along $f$ by 
\begin{equation}
\psi_f( {\cal F} ) = i^{-1} {\rm R} (j\circ\pi)_*(j\circ\pi)^{-1} {\cal F}
\ \in {\bf D}^{\mathrm{b}} (X_0).
\end{equation}
Moreover, we define the vanishing cycle 
complex $\phi_f( {\cal F} )\in {\bf D}^{\mathrm{b}} (X_0)$ of ${\cal F} \in {\bf D}^{\mathrm{b}} (X)$ 
along $f$ so that it fits into the distinguished triangle 
\begin{equation}
i^{-1} {\cal F} \longrightarrow \psi_f( {\cal F} ) \longrightarrow 
\phi_f( {\cal F} ) \overset{+1}{\longrightarrow}, 
\end{equation}
where the morphism $i^{-1} {\cal F}  \longrightarrow \psi_f( {\cal F} )$ 
is induced by the one 
${\rm id} \longrightarrow {\rm R} (j\circ\pi)_*(j\circ\pi)^{-1}$ 
of functors (for the more precise definition, see 
Kashiwara-Schapira \cite[page 351]{K-S}).

\label{prp.7.1.002}
{\rm (see e.g. \cite[Exercise VIII.15]{K-S} and 
\cite[Proposition 4.2.11]{Dimca})}  
Let $\rho \colon Y  \longrightarrow X$ be a 
morphism of complex manifolds 
and $f\colon X  \longrightarrow {\mathbb C}$ a non-constant 
holomorphic function on $X$. We set 
$g:=f\circ\rho\colon Y  \longrightarrow {\mathbb C}$ and 
\begin{equation}
X_0=f^{-1}(0)\subset X,\quad Y_0=g^{-1}(0)=\rho^{-1}(X_0)\subset Y. 
\end{equation}
Let $\rho|_{Y_0}\colon Y_0 \longrightarrow X_0$ be the 
restriction of $\rho$ to $Y_0\subset Y$ and assume that 
$\rho \colon Y  \longrightarrow X$ is proper on 
the support of ${\cal G} \in {\bf D}^{\mathrm{b}} (Y)$. Then there exist isomorphisms 
\begin{equation}
\psi_f( {\rm R} \rho_* {\cal G} ) \simeq {\rm R} (\rho|_{Y_0})_*\psi_g( {\cal G} ), \qquad 
\phi_f( {\rm R} \rho_* {\cal G} ) \simeq {\rm R} (\rho|_{Y_0})_*\phi_g( {\cal G} ). 
\end{equation}

\label{thm.7.2.004}
{\rm (see e.g. \cite[Proposition 4.2.2]{Dimca} 
and \cite[Theorem 2.6]{Tak-3})} 
For any point 
$x \in X_0$ of $X_0=f^{-1}(0)$ there exist isomorphisms 
\begin{equation}
H^j \psi_f( {\mathbb C}_X )_x \simeq H^j(F_x; {\mathbb C} ),
\quad 
H^j \phi_f(  {\mathbb C}_X )_x \simeq \widetilde{H}^j(F_x; {\mathbb C} )
\qquad (j\in{\mathbb Z}), 
\end{equation}
where $\widetilde{H}^j(F_x; {\mathbb C} )$ stand for 
the reduced cohomology groups of $F_x$. 
Moreover these isomorphisms are compatible 
with the monodromy automorphisms of the both sides.

\label{thm.7.2.006}
For any constructible sheaf ${\cal F} \in {\bf D}_{\mathrm{c}}^{\mathrm{b}} (X)$ on $X$ and 
any point $x \in X_0$ of $X_0=f^{-1}(0)$ there exist isomorphisms 
\begin{equation}
 H^j \psi_f( {\cal F} )_x \simeq H^j(F_x; {\cal F} )
 \qquad (j\in{\mathbb Z}).
\end{equation}

\label{thm.7.1.004}
{\rm (see e.g. \cite[Proposition 8.6.3]{K-S}, 
\cite[page 103]{Dimca} and \cite[Theorem 4.0.2 and Lemma 4.2.1]{Sch})} 
Assume that ${\cal F} \in {\bf D}^{\mathrm{b}}(X)$ is constructible. Then 
$\psi_f( {\cal F} ), \phi_f( {\cal F} ) \in  {\bf D}^{\mathrm{b}}(X_0)$ 
are also constructible. Namely there exist two  
functors 
\begin{equation}
\psi_f(  \cdot  ),\ 
\phi_f(  \cdot  ) \colon {\bf D}_{\mathrm{c}}^{\mathrm{b}} (X) \longrightarrow {\bf D}_{\mathrm{c}}^{\mathrm{b}} (X_0).
\end{equation}

{\rm (Broughton \cite{Broughton})} \label{tame}
Assume that $f$ is tame at infinity. 
Then for any point $c \in {\mathbb C}$ its fiber $f^{-1}(c)$ of $f$ 
is homotopy equivalent to the bouquet of some 
$(n-1)$-dimensional spheres $S^{n-1}$: 
\begin{equation}
f^{-1}(c)  \sim  S^{n-1}\vee\cdots\vee S^{n-1}.
\end{equation}
Moreover the number of spheres $S^{n-1}$ in this bouquet 
decomposition is equal to $\mu - \mu_c \geq 0$. 
In particular, we have isomorphisms 
\begin{equation}
H^j(f^{-1}(c); {\mathbb C} ) \simeq 
\begin{cases}
\ {\mathbb C} & (j=0) \\
& \\
\ {\mathbb C}^{\mu - \mu_c} & (j=n-1) \\
 & \\
\ 0 & (j \neq 0,n-1). 
\end{cases}
\end{equation}

\label{prp.L-T}
{\rm (Libgober-Tib{\u a}r \cite[Proposition 3.1]{L-T})}  
Asuume that $c \in {\mathbb C} \setminus \Sigma$. Then 
the hypersurface complement 
$X \setminus f^{-1}(c)$ has the homotopy type of 
\begin{equation}
S^1 \vee (S^{n} \vee \cdots \vee S^{n}), 
\end{equation}
where $S^{n} \vee \cdots \vee S^{n}$ is 
the bouquet of the $\mu$ copies of the $n$-sphere $S^{n}$.

\label{prp.gen-L-T} 
Asuume that $n \geq 3$ and $c \in \Sigma$. Then for the complement 
$X \setminus f^{-1}(c)$ of the singular fiber $f^{-1}(c)$ of 
$f$ we have 
\begin{equation}
H^j(X \setminus f^{-1}(c); {\mathbb C} ) \simeq 0 \quad 
(j \not= 0,1,n-1,n) 
\end{equation}
and $H^0(X \setminus f^{-1}(c); {\mathbb C} ) \simeq 
H^1(X \setminus f^{-1}(c); {\mathbb C} ) \simeq {\mathbb C}$. Moreover we have 
\begin{equation}
\dim H^n(X \setminus f^{-1}(c); {\mathbb C} ) - 
\dim H^{n-1}(X \setminus f^{-1}(c); {\mathbb C} )= 
\mu - \mu_c.
\end{equation}

{\rm (Nguyen-Takeuchi \cite{N-T})} For 
${\cal F} \in {\bf D}^{\mathrm{b}}(X)$ we set 
\begin{equation}
\psi_f^{{\rm mero}}( {\cal F} ):= \psi_t( {\rm R} i_{f*}
( {\cal F} |_{X \setminus Q^{-1}(0)}) ) 
\qquad \in {\bf D}^{\mathrm{b}}(X_0). 
\end{equation}
We call $\psi_f^{{\rm mero}}( {\cal F} )$ the meromorphic 
nearby cycle complex of ${\cal F}$ along $f$.

\label{lem-nc-1} 
{\rm (see \cite[Lemma 2.1]{N-T})} 
\begin{enumerate}
\item[\rm{(i)}] The support of $\psi_f^{{\rm mero}}( {\cal F} )$ is 
contained in $P^{-1}(0)$. 
\item[\rm{(ii)}] There exists an isomorphism 
\begin{equation}
\psi_f^{{\rm mero}}( {\cal F} ) \overset{\sim}{\longrightarrow} 
\psi_f^{{\rm mero}}( {\rm R} 
\Gamma_{X \setminus (P^{-1}(0) \cup Q^{-1}(0))} 
( {\cal F} )). 
\end{equation}
\end{enumerate}

\label{the-nc-1} 
{\rm (see \cite[Lemma 2.1 and Theorem 2.2]{N-T})} 
Assume that ${\cal F} \in {\bf D}^{\mathrm{b}}(X)$ is constructible. Then we have 
\begin{enumerate}
\item[\rm{(i)}] 
$\psi_f^{{\rm mero}}( {\cal F} ) \in {\bf D}^{\mathrm{b}}(X)$ is also constructible. 
\item[\rm{(ii)}] If moreover ${\cal F} \in {\bf D}^{\mathrm{b}}(X)$ is perverse, then 
$\psi_f^{{\rm mero}}( {\cal F} )[-1] \in {\bf D}^{\mathrm{b}}(X)$ is also perverse. 
\item[\rm{(iii)}] For any point $x \in P^{-1}(0)$ 
there exist isomorphisms 
\begin{equation}
H^j \psi_f^{{\rm mero}}( {\cal F} )_x \simeq H^j (F_x; {\cal F} ) 
 \qquad (j \in {\mathbb Z} ). 
\end{equation}
Moreover these isomorphisms are 
compatible with the monodromy automorphisms 
on the both sides. 
\end{enumerate}

\label{lem-1} 
{\rm (see \cite[Lemma 2.2]{Tak-4})}
\begin{enumerate}
\item[\rm{(i)}] The support of $\psi_f^{{\rm mero,c}}( {\cal F} )$ is 
contained in $P^{-1}(0)$. 
\item[\rm{(ii)}] There exists an isomorphism 
\begin{equation}
\psi_f^{{\rm mero,c}}( {\cal F} ) \overset{\sim}{\longrightarrow} 
\psi_f^{{\rm mero,c}}( {\cal F}_{X \setminus (P^{-1}(0) \cup Q^{-1}(0))} ). 
\end{equation}
\end{enumerate}

\label{the-1} 
{\rm (see \cite[Lemma 2.2 and Theorem 2.4]{Tak-4})}
Assume that ${\cal F} \in {\bf D}^{\mathrm{b}}(X)$ is constructible. Then we have 
\begin{enumerate}
\item[\rm{(i)}] 
$\psi_f^{{\rm mero,c}}( {\cal F} ) \in {\bf D}^{\mathrm{b}}(X)$ is also constructible. 
\item[\rm{(ii)}] If moreover ${\cal F} \in {\bf D}^{\mathrm{b}}(X)$ is perverse, then 
$\psi_f^{{\rm mero,c}}( {\cal F} )[-1] \in {\bf D}^{\mathrm{b}}(X)$ is also perverse. 
\item[\rm{(iii)}] 
For any point $x \in P^{-1}(0)$ 
there exist isomorphisms 
\begin{equation}
H^j \psi_f^{{\rm mero,c}}( {\cal F} )_{x} \simeq 
H^j_c ( \overline{F_{x}} \setminus Q^{-1}(0) ; {\cal F} )
 \qquad (j \in {\mathbb Z} ),  
\end{equation}
where $H^j_c ( \cdot )$ stands for the hypercohomology 
group with compact support. 
\end{enumerate}

\label{lem-2} 
{\rm (see \cite[Lemma 2.5]{Tak-4})}
\begin{enumerate}
\item[\rm{(i)}] The support of $\phi_f^{{\rm mero,c}}( {\cal F} )$ is 
contained in $P^{-1}(0)$. 
\item[\rm{(ii)}] There exists an isomorphism 
\begin{equation}
\phi_f^{{\rm mero,c}}( {\cal F} ) \overset{\sim}{\longrightarrow} 
\phi_f^{{\rm mero,c}}( {\cal F}_{X \setminus Q^{-1}(0)} ). 
\end{equation}
\end{enumerate}

\label{vc-lem} 
In the situation as above, for any $c \in {\mathbb C}$ we have a vanishing 
\begin{equation}
H^j \phi_{t-c} {\rm R} f_! {\mathbb C}_U \simeq 0 \quad (j \not= n-1).  
\end{equation}

\label{MainT-1}
In the situation as above, assume also that $n \geq 3$. Then 
for any generic fiber $f^{-1}(c) \subset U=X \setminus Q^{-1}(0)$ 
($c \in {\mathbb C} \setminus \Sigma$) of $f: U=X \setminus Q^{-1}(0) \longrightarrow {\mathbb C}$ 
we have 
\begin{equation}
H^j(f^{-1}(c); {\mathbb C} ) \simeq 0 \quad (j \not= 0,1,n-1) 
\end{equation}
and $H^0(f^{-1}(c); {\mathbb C} ) \simeq H^1(f^{-1}(c); {\mathbb C} ) \simeq {\mathbb C}$.

\label{acs-lem} 
Let ${\cal F}$ be an algebraic constructible sheaf on the affine line ${\mathbb C}$. 
Then we have 
\begin{equation}
H^j_c( {\mathbb C} ; {\cal F} ) \simeq 0 \quad (j \notin [0,2]).  
\end{equation}

\label{conj-1}
In the situation of Theorem \ref{MainT-1}, for 
any fiber $f^{-1}(c) \subset U=X \setminus Q^{-1}(0)$ 
($c \in {\mathbb C}$) of $f: U=X \setminus Q^{-1}(0) \longrightarrow {\mathbb C}$ 
we have 
\begin{equation}
H^j(f^{-1}(c); {\mathbb C} ) \simeq 0 \quad (j \not= 0,1,n-1) 
\end{equation}
and $H^0(f^{-1}(c); {\mathbb C} ) \simeq H^1(f^{-1}(c); {\mathbb C} ) \simeq {\mathbb C}$.

\label{conj-2}
In the situation of Theorem \ref{MainT-1}, 
any generic fiber $f^{-1}(c) \subset U=X \setminus Q^{-1}(0)$ 
($c \in {\mathbb C} \setminus \Sigma$) of $f: U=X \setminus Q^{-1}(0) \longrightarrow {\mathbb C}$ 
has the homotopy type of 
\begin{equation}
S^1 \vee (S^{n-1} \vee \cdots \vee S^{n-1}).
\end{equation}

\label{MainT-2}
In the situation of Theorem \ref{MainT-1}, 
for any generic fiber $f^{-1}(c) \subset U=X \setminus Q^{-1}(0)$ 
($c \in {\mathbb C} \setminus \Sigma$) of $f: U=X \setminus Q^{-1}(0) \longrightarrow {\mathbb C}$ 
we have 
\begin{equation}
\dim H^{n-1}(f^{-1}(c); {\mathbb C} ) = \mu_f-( \mu - \mu_0),  
\end{equation}
where we set 
\begin{equation}
\mu_f := \sum_{i=1}^l \dim  H^{n-1} \phi_{t-c_i} {\rm R} f_! {\mathbb C}_U. 
\end{equation}
In particular, there exists an inequality 
\begin{equation}
\mu_f \geq \mu - \mu_0.  
\end{equation}

We define a function $\varphi : {\mathbb C} \longrightarrow {\mathbb R}$ by 
$\varphi (t):= |t-c|$ ($t \in {\mathbb C}$). Then we prove the assertion 
by applying a backward Morse theory to ${\rm R} f_! {\mathbb C}_U$ and $\varphi$. 
First of all, for sufficiently large $r \gg 0$ there exists an isomorphism 
\begin{equation}
{\rm R}\Gamma_c( \{ \varphi <r  \} ; {\rm R} f_! {\mathbb C}_U) 
\simeq {\rm R}\Gamma_c(U; {\mathbb C}_U)
\end{equation}
and hence by Propositions \ref{prp.L-T} and \ref{prp.gen-L-T} we have 
\begin{equation}
{\rm R}\Gamma_c( \{ \varphi <r  \} ; {\rm R} f_! {\mathbb C}_U)  \simeq 0 \quad 
(j \not= n,n+1,2n-1,2n-2) 
\end{equation}
and $H^{2n-1}_c( \{ \varphi <r  \} ; {\rm R} f_! {\mathbb C}_U) \simeq 
H^{2n}_c( \{ \varphi <r  \} ; {\rm R} f_! {\mathbb C}_U) \simeq {\mathbb C}$. Moreover we have 
\begin{equation}
\dim H^n_c ( \{ \varphi <r  \} ; {\rm R} f_! {\mathbb C}_U) - 
\dim H^{n+1}_c ( \{ \varphi <r  \} ; {\rm R} f_! {\mathbb C}_U)= 
\mu - \mu_0. 
\end{equation}
For a fixed $r>0$ and $0< \varepsilon \ll 1$ let us consider how the 
cohomology groups of 
${\rm R}\Gamma_c( \{ \varphi <r- \varepsilon \} ; {\rm R} f_! {\mathbb C}_U)$ 
change from those of 
${\rm R}\Gamma_c( \{ \varphi <r+ \varepsilon \} ; {\rm R} f_! {\mathbb C}_U)$. 
For this purpose, we can use the distinguished triangle 
\begin{align}\label{d-t-3} 
\begin{split} 
& {\rm R}\Gamma_c( \{ \varphi <r- \varepsilon \} ; {\rm R} f_! {\mathbb C}_U)
 \longrightarrow {\rm R}\Gamma_c ( \{ \varphi <r+ \varepsilon \} ; {\rm R} f_! {\mathbb C}_U)
\\ 
& \longrightarrow 
{\rm R}\Gamma_c( \{ r- \varepsilon \leq \varphi <r+ \varepsilon   \} ; {\rm R} f_! {\mathbb C}_U)
\overset{+1}{\longrightarrow}. 
\end{split} 
\end{align}
For $1 \leq i \leq l$ such that $\varphi (c_i)=|c_i-c|=r$ and 
$\delta >0$ such that $0< \varepsilon < \delta \ll 1$ we set 
$D_{\delta}(c_i):= \{ t \in {\mathbb C} \ | \ |t-c_i| < \delta \} 
\subset {\mathbb C}$. Then we define a closed subset 
$K \subset {\mathbb C}$ by $K:= \sqcup_{i: \varphi (c_i)=r} 
\overline{D_{\delta}(c_i)}$ to obtain a 
distinguished triangle 
\begin{align}
\begin{split}
& {\rm R}\Gamma_c( \{ r- \varepsilon \leq \varphi <r+ \varepsilon   \} \setminus K ; {\rm R} f_! {\mathbb C}_U)
 \longrightarrow {\rm R}\Gamma_c ( \{  r- \varepsilon \leq \varphi <r+ \varepsilon \} ; {\rm R} f_! {\mathbb C}_U)
\\ 
& \longrightarrow 
{\rm R}\Gamma_c( \{ r- \varepsilon \leq \varphi <r+ \varepsilon   \} \cap K ; {\rm R} f_! {\mathbb C}_U)
\overset{+1}{\longrightarrow}. 
\end{split}
\end{align}
We can easily see that 
\begin{equation}
{\rm R}\Gamma_c( \{ r- \varepsilon \leq \varphi <r+ \varepsilon   \} \setminus K ; {\rm R} f_! {\mathbb C}_U)
\simeq 
{\rm R}\Gamma_c( {\mathbb C} ; (
{\rm R} f_! {\mathbb C}_U)_{\{ r- \varepsilon \leq \varphi <r+ \varepsilon   \} \setminus K} )
\simeq 0. 
\end{equation}
Moreover, for any $1 \leq i \leq l$ such that $\varphi (c_i)=|c_i-c|=r$ 
there exist isomorphisms 
\begin{align}
\begin{split}
& {\rm R}\Gamma_c( \{ r- \varepsilon \leq \varphi <r+ \varepsilon   \} \cap \overline{D_{\delta}(c_i)}
 ; {\rm R} f_! {\mathbb C}_U)
\\
& \simeq 
{\rm R}\Gamma_c( {\mathbb C} ; (
{\rm R} f_! {\mathbb C}_U)_{\{ r- \varepsilon \leq \varphi <r+ \varepsilon   \} 
\cap \overline{D_{\delta}(c_i)}} )
\simeq 
{\rm R}\Gamma_{\{ \varphi \leq r \}}( \overline{D_{\delta}(c_i)}; 
{\rm R} f_! {\mathbb C}_U)
\\
& \simeq 
\phi_{t-c_i} {\rm R} f_! {\mathbb C}_U [-1].
\end{split}
\end{align}
By Lemma \ref{vc-lem}, this implies that we have 
\begin{equation}
H^j_c( \{ r- \varepsilon \leq \varphi <r+ \varepsilon   \} ; {\rm R} f_! {\mathbb C}_U)
\simeq 0 \quad (j \not= n) 
\end{equation}
and 
\begin{equation}
\dim H^n_c( \{ r- \varepsilon \leq \varphi <r+ \varepsilon   \} ; {\rm R} f_! {\mathbb C}_U)
= \sum_{i: \varphi (c_i)=r} \dim H^{n-1} \phi_{t-c_i} {\rm R} f_! {\mathbb C}_U. 
\end{equation}
On the other hand, for $0<r \ll 1$ it follows from the 
condition $c \notin \Sigma$ that there exists an isomorphism 
\begin{equation}
{\rm R}\Gamma_c( \{ \varphi <r  \} ; {\rm R} f_! {\mathbb C}_U)[2] 
\simeq ({\rm R} f_! {\mathbb C}_U)_c. 
\end{equation}
By \eqref{van-di} for $0<r \ll 1$ we thus obtain a vanishing 
\begin{equation}
H^j_c( \{ \varphi <r  \} ; {\rm R} f_! {\mathbb C}_U) 
\simeq 0 \quad (j \notin [n+1, 2n]). 
\end{equation}
Combining these results together, 
the assertion immediately follows from the 
cohomology long exact sequence associated to 
the distinguished triangle \eqref{d-t-3}. 
This completes the proof. 
\hfill $\Box$
